import numpy as np

def pauli_rgb(HH, HV, VV, VH):
    r = np.abs(HH - VV) / np.sqrt(2.0)
    g = (np.abs(HV) + np.abs(VH)) / np.sqrt(2.0)
    b = np.abs(HH + VV) / np.sqrt(2.0)

    def to_uint8(channel):
        peak = float(np.max(channel))
        if peak <= 0:
            return np.zeros_like(channel, dtype=np.uint8)
        scaled = np.clip(channel / peak, 0.0, 1.0)
        return (scaled * 255.0).astype(np.uint8)

    return np.stack([to_uint8(r), to_uint8(g), to_uint8(b)], axis=-1)
